            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" fill=\"#FFD700\" text-anchor=\"middle\" font-weight=\"bold\">Wealth vs. Income</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#aaaaaa\" text-anchor=\"middle\">What you earn vs. what you keep</text><rect x=\"100\" y=\"180\" width=\"420\" height=\"700\" fill=\"none\" stroke=\"#ef4444\" stroke-width=\"3\" rx=\"10\"/><text x=\"310\" y=\"230\" font-size=\"26\" fill=\"#ef4444\" text-anchor=\"middle\" font-weight=\"bold\">INCOME</text><text x=\"310\" y=\"280\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">What you earn</text><text x=\"310\" y=\"320\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">(annually)</text><text x=\"310\" y=\"400\" font-size=\"18\" fill=\"#aaaaaa\" text-anchor=\"middle\">Surgeon: $300,000/yr</text><text x=\"310\" y=\"440\" font-size=\"18\" fill=\"#aaaaaa\" text-anchor=\"middle\">Lawyer: $200,000/yr</text><text x=\"310\" y=\"480\" font-size=\"18\" fill=\"#aaaaaa\" text-anchor=\"middle\">Teacher: $60,000/yr</text><text x=\"310\" y=\"600\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Shows on paychecks</text><text x=\"310\" y=\"640\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Taxed every year</text><text x=\"310\" y=\"680\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Easy to spend</text><text x=\"310\" y=\"780\" font-size=\"22\" fill=\"#ef4444\" text-anchor=\"middle\">Visible</text><rect x=\"580\" y=\"180\" width=\"420\" height=\"700\" fill=\"none\" stroke=\"#0ea5e9\" stroke-width=\"3\" rx=\"10\"/><text x=\"790\" y=\"230\" font-size=\"26\" fill=\"#0ea5e9\" text-anchor=\"middle\" font-weight=\"bold\">WEALTH</text><text x=\"790\" y=\"280\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">What you keep</text><text x=\"790\" y=\"320\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">(net worth)</text><text x=\"790\" y=\"400\" font-size=\"18\" fill=\"#aaaaaa\" text-anchor=\"middle\">Assets − Liabilities</text><text x=\"790\" y=\"440\" font-size=\"18\" fill=\"#aaaaaa\" text-anchor=\"middle\">Surgeon: −$100,000</text><text x=\"790\" y=\"480\" font-size=\"18\" fill=\"#aaaaaa\" text-anchor=\"middle\">Teacher: $450,000</text><text x=\"790\" y=\"600\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Compounds over time</text><text x=\"790\" y=\"640\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Buys freedom</text><text x=\"790\" y=\"680\" font-size=\"22\" fill=\"#ffffff\" text-anchor=\"middle\">Hard to build</text><text x=\"790\" y=\"780\" font-size=\"22\" fill=\"#0ea5e9\" text-anchor=\"middle\">Invisible</text><text x=\"550\" y=\"970\" font-size=\"22\" fill=\"#FFD700\" text-anchor=\"middle\" font-weight=\"bold\">Net Worth = Assets − Liabilities</text></svg>",
